vt=[];vte=[];
vt[vt.length]=`<div id="text_86" class="textshirt mergershirt" style="top: 47px; left: 407px; font-size: 26px;">&nbsp;</div>`;
vt[vt.length]=`<div id="text_83" class="textshirt mergershirt" style="width: 335px; white-space: normal; top: 46px; left: 407px; height: 360px;">Er griff nach seinem Telefon. Eine Sekunde lang dachte er, er würde den Flug buchen. Dann öffnete er die Kamera. Er machte ein Foto vom Garten. Er sah es sich an. Es war kein sehr gutes Foto. Das Licht war falsch. Die Hecke sah seltsam aus. Der Vogel war nur ein kleiner schwarzer Punkt. <br><br>Er lachte. Dann steckte er das Telefon weg.<br> Der Morgen wurde zum Nachmittag. Der Nachmittag wurde etwas sanfter. Und er, der fast alles hätte kaufen können, verstand endlich etwas ganz Einfaches. Er musste die Vergangenheit nicht kaufen. Er brauchte es nicht zu wiederholen. Er musste die Gegenwart nicht verbessern, indem er sie in einen anderen Ort verwandelte. Er musste nur dort sein, wo er bereits war. Das war er. Und ausnahmsweise war das genug.</div>`;
vt[vt.length]=`<div id="text_84" class="textshirt mergershirt" style="width: 335px; white-space: normal; top: 303px; left: 901px; height: 360px;">A Story by ChatGPT<br>translated by Google</div>`;

vte[vte.length]=`<div id="text_86" class="textshirt mergershirt`+transws+`" style="top: 47px; left: 407px; font-size: 26px;">&nbsp;</div>`;
vte[vte.length]=`<div id="text_83" class="textshirt mergershirt`+transws+`" style="width: 335px; white-space: normal; top: 46px; left: 407px; height: 360px;">he reached for his phone. For one second, he thought he would book the flight. Then he opened the camera. He took a photograph of the garden. He looked at it. It was not a very good photograph. The light was wrong. The hedge looked strange. The bird was only a small black dot. <br><br>He laughed. Then he put the phone away.<br> The morning became afternoon. The afternoon became something softer. And he, who could have bought almost anything, finally understood something very simple. He did not need to buy the past. He did not need to repeat it. He did not need to improve the present by turning it into somewhere else. He only needed to be where he already was. So he was. And for once, that was enough.</div>`;
vte[vte.length]=`<div id="text_84" class="textshirt mergershirt`+transws+`" style="width: 335px; white-space: normal; top: 303px; left: 901px; height: 360px;">A Story by ChatGPT<br>translated by Google</div>`;

